import {NaverMapView} from './naver-map.js';
import {CloudStore,SESSION_KEY,cloudError,getMapConfig} from './cloud-store.js';
import {generatePersonalKey} from './cloud-client.js';
const paths={pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',close:'m6 6 12 12M6 18 18 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',shield:'m12 3 9 4v5c0 5-9 9-9 9s-9-4-9-9V7l9-4Zm-4 9 3 3 5-6',share:'M12 16V3m-4 4 4-4 4 4M5 12v8h14v-8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8m3 10v-2a4 4 0 0 0-3-4',coffee:'M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm13 1h2a3 3 0 0 1 0 6h-2 M7 2v3m5-3v3',food:'M5 3v7m4-7v7M3 3v5a4 4 0 0 0 8 0V3M7 12v9M20 3c-5 2-5 10 0 10V3Zm0 10v8',bag:'M5 7h14l2 14H3L5 7Zm3 0V5a4 4 0 0 1 8 0v2',tree:'m12 2-7 9h4l-6 7h18l-6-7h4l-7-9Zm0 16v4',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',locate:'M12 2v3m0 14v3M2 12h3m14 0h3M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0',minus:'M5 12h14',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L19 6',logout:'M9 4H4v16h5m5-12 4 4-4 4m-5-4h14',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15v5'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.pin}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={users:[{id:'me',name:'서연',color:'#e7ecd8'},{id:'min',name:'민수',color:'#ede2d5'},{id:'ji',name:'지연',color:'#e2e7dc'},{id:'su',name:'수빈',color:'#e8dfcf'}],rooms:[{id:'friends',name:'우리 동네 메이트',emoji:'🌿',description:'취향이 통하는 사람들과, 좋아하는 공간을 나눠요.',master:'me',code:'MATE24',members:['me','min','ji','su'],bans:[],pending:[]},{id:'coffee',name:'커피 한 잔 할래요',emoji:'☕',description:'커피와 공간을 좋아하는 우리의 지도',master:'ji',code:'COFFEE',members:['me','ji'],bans:[],pending:[]},{id:'travel',name:'주말의 작은 여행',emoji:'🧳',description:'멀리 가지 않아도 좋은, 주말의 발견',master:'me',code:'WEEKND',members:['me','su'],bans:[],pending:[]}],places:[{id:'p1',name:'센터커피 서울숲점',category:'카페',address:'서울 성동구 서울숲2길 28-11',lat:37.5474,lng:127.0433,owner:'min',rooms:['friends','coffee']},{id:'p2',name:'성수다락',category:'맛집',address:'서울 성동구 뚝섬로9길 20',lat:37.5457,lng:127.0491,owner:'me',rooms:['friends']},{id:'p3',name:'오브젝트 성수',category:'기타',address:'서울 성동구 서울숲길 일대 · 예시 위치',lat:37.5498,lng:127.0421,owner:'ji',rooms:['friends']},{id:'p4',name:'서울숲',category:'기타',address:'서울 성동구 뚝섬로 273',lat:37.5445,lng:127.0384,owner:'su',rooms:['friends','travel']},{id:'p5',name:'대림창고',category:'카페',address:'서울 성동구 성수이로 78',lat:37.5417,lng:127.0563,owner:'me',rooms:['friends','coffee']},{id:'p6',name:'소문난성수감자탕',category:'맛집',address:'서울 성동구 연무장길 45',lat:37.5416,lng:127.0541,owner:'min',rooms:['friends']},{id:'p7',name:'테디스오븐',category:'카페',address:'서울 성동구 서울숲2길 43',lat:37.5485,lng:127.0427,owner:'me',rooms:[]}],reviews:[{place:'p1',user:'min',visited:true,rating:5,custom:[{label:'커피 맛',score:5},{label:'의자 편안함',score:3}],comment:'산책 끝에 마시는 플랫화이트. 창가 자리가 특히 좋아요.'},{place:'p1',user:'ji',visited:true,rating:4,custom:[{label:'분위기',score:5},{label:'디저트',score:4}],comment:'서울숲 바라보며 잠깐 쉬어가기 좋은 곳 🌿'},{place:'p1',user:'su',visited:true,rating:5,custom:[{label:'커피 맛',score:5}],comment:'산미 있는 커피를 좋아하면 추천! 주말엔 조금 붐벼요.'},{place:'p2',user:'me',visited:true,rating:4,custom:[{label:'맛',score:5}],comment:'오므라이스가 부드러워요. 점심에는 웨이팅이 있어요.'},{place:'p4',user:'su',visited:true,rating:5,custom:[{label:'산책하기',score:5}],comment:'해질 무렵 걸으면 참 좋아요.'},{place:'p5',user:'me',visited:true,rating:4,custom:[{label:'공간',score:5}],comment:'천장이 높아서 시원하고 작업하기 좋아요.'}]};
let db;try{db=JSON.parse(localStorage.getItem('jidomate-v1'))||structuredClone(initial);}catch{db=structuredClone(initial);}
let cloud=null,cloudBusy=false,cloudKey='',cloudUnsure=false;
let roomId='friends',selected='p1',filter='전체',query='',view='map',onlyVisited=false;
const naverView=new NaverMapView();
let naverNotice='네이버 지도 설정 전 · 임시 OpenStreetMap';
let searchResults=[];
let regionCity='',regionDistrict='',detailOpen=false,statusVisited=false,statusWanted=false;
let extraCategories=[];try{extraCategories=JSON.parse(localStorage.getItem('placemate-categories')||'[]').filter(c=>typeof c==='string'&&c.trim()&&c.length<=30).slice(0,30);}catch{}
function categories(){return [...new Set(['맛집','카페','기타',...extraCategories,...db.places.filter(inCurrentMap).map(p=>p.category)])];}
function wantedPlace(p){return !visitedPlace(p)&&db.places.some(m=>m.owner==='me'&&m.wanted&&(m.canonicalId||m.id)===(p.canonicalId||p.id));}
function visitedPlace(p){return db.reviews.some(r=>samePlace(r,p.id)&&r.user==='me'&&r.visited);}
function statusMatches(p){return (!statusVisited&&!statusWanted)||(statusVisited&&visitedPlace(p))||(statusWanted&&wantedPlace(p));}
let center={lat:37.5462,lng:127.046},zoom=15,resizeObserver;
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const user=id=>db.users.find(u=>u.id===id)||{id,name:'알 수 없음',color:'#eceee5'};
const room=()=>db.rooms.find(r=>r.id===roomId);
const avatar=id=>`<span class="avatar" style="background:${user(id).color}">${esc(user(id).name.slice(0,1))}</span>`;
const categoryIcon=c=>({'카페':'coffee','맛집':'food','쇼핑':'bag','산책':'tree'}[c]||'pin');
const save=()=>{if(cloud?.active)return;try{localStorage.setItem('jidomate-v1',JSON.stringify(db));}catch{toast('저장 공간이 부족해 기록을 저장하지 못했어요.');}};
let toastTimer;function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3000);}
const placeKey=id=>db.places.find(p=>p.id===id)?.canonicalId||id;
const samePlace=(r,id)=>r.place===placeKey(id);

const regionAliases={'서울특별시':'서울','서울시':'서울','부산광역시':'부산','대구광역시':'대구','인천광역시':'인천','광주광역시':'광주','대전광역시':'대전','울산광역시':'울산','세종특별자치시':'세종','경기도':'경기','강원도':'강원','강원특별자치도':'강원','충청북도':'충북','충청남도':'충남','전라북도':'전북','전북특별자치도':'전북','전라남도':'전남','경상북도':'경북','경상남도':'경남','제주특별자치도':'제주','제주도':'제주'};
const regionCities=['서울','부산','대구','인천','광주','대전','울산','세종','경기','강원','충북','충남','전북','전남','경북','경남','제주'];
function placeRegion(p){const words=p.address.trim().split(/\s+/);const city=regionAliases[words[0]]||words[0];let district=words[1]||'';if(/시$/.test(district)&&/구$/.test(words[2]||''))district+=' '+words[2];return {city,district};}
function inCurrentMap(p){return roomId==='personal'?p.owner==='me':p.rooms.includes(roomId)&&room()?.members.includes(p.owner);}
function regionHTML(){const districts=[...new Set(db.places.filter(inCurrentMap).map(placeRegion).filter(r=>r.city===regionCity).map(r=>r.district).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));return '<div class="region-controls"><label>지역 선택<select id="region-city" aria-label="큰 지역"><option value="">전체 지역</option>'+regionCities.map(c=>'<option value="'+c+'"'+(regionCity===c?' selected':'')+'>'+c+'</option>').join('')+'</select></label><label>시·군·구<select id="region-district" aria-label="시·군·구"'+(!regionCity?' disabled':'')+'><option value="">전체</option>'+districts.map(d=>'<option value="'+esc(d)+'"'+(regionDistrict===d?' selected':'')+'>'+esc(d)+'</option>').join('')+'</select></label>'+(regionCity?'<button class="region-tag" data-action="clear-region" aria-label="지역 필터 해제">'+esc(regionCity)+' · '+esc(regionDistrict||'전체')+' <span aria-hidden="true">×</span></button>':'')+'</div><div class="status-controls"><label><input id="status-wanted" type="checkbox" '+(statusWanted?'checked':'')+'> 가보고 싶은 곳</label><label><input id="status-visited" type="checkbox" '+(statusVisited?'checked':'')+'> 가본 곳</label><small>둘 다 선택하면 함께 표시해요</small></div>';}
function placeListHTML(){const places=visiblePlaces();return '<div class="place-list-heading"><h2>우리의 장소</h2><span>'+places.length+'곳</span></div><div class="place-rows">'+(places.length?places.map(p=>'<button class="place-row" data-place="'+esc(p.id)+'"><span class="place-row-top"><strong>'+esc(p.name)+'</strong><span class="place-row-rating">★ '+rating(p)+'</span></span><small>'+esc(p.address)+'</small><span class="place-state">'+(visitedPlace(p)?'✓ 가본 곳':wantedPlace(p)?'♡ 가보고 싶은 곳':'')+'</span></button>').join(''):'<p class="empty">이 조건에 맞는 장소가 없어요.</p>')+'</div>';}
function openPlaceDetail(id){selected=id;detailOpen=true;const el=document.querySelector('#detail');el.hidden=false;el.innerHTML='<button class="detail-close" data-action="close-detail">상세보기 닫기 ×</button>'+detailHTML();drawMap();el.scrollIntoView({behavior:'smooth',block:'start'});}

function visiblePlaces(){const results=db.places.filter(p=>roomId==='personal'?p.owner==='me':p.rooms.includes(roomId)&&room()?.members.includes(p.owner)).filter(p=>(!regionCity||(placeRegion(p).city===regionCity&&(!regionDistrict||placeRegion(p).district===regionDistrict)))&&statusMatches(p)&&(filter==='전체'||p.category===filter)&&(!onlyVisited||db.reviews.some(r=>samePlace(r,p.id)&&r.user==='me'&&r.visited))&&(!query||`${p.name} ${p.address} ${user(p.owner).name}`.toLowerCase().includes(query.toLowerCase())));if(!cloud?.active||roomId==='personal')return results;const pins=new Map();for(const p of results){const key=p.canonicalId||p.id;const current=pins.get(key);if(!current||p.owner==='me')pins.set(key,p);}return [...pins.values()];}
function reviews(p){return db.reviews.filter(r=>samePlace(r,p.id)&&(roomId==='personal'?r.user==='me':room()?.members.includes(r.user)));}
function rating(p){const a=reviews(p).filter(r=>r.visited&&r.rating>0);return a.length?(a.reduce((s,r)=>s+r.rating,0)/a.length).toFixed(1):'—';}
function art(category){const cafe=category==='카페';return `<svg viewBox="0 0 600 310" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${cafe?'카페 공간':'장소'} 분위기 일러스트"><defs><linearGradient id="wall" x2="1" y2="1"><stop stop-color="#d7d4ba"/><stop offset="1" stop-color="#b3b69b"/></linearGradient><linearGradient id="window"><stop stop-color="#b7c7ad"/><stop offset="1" stop-color="#d3dbc2"/></linearGradient></defs><path fill="url(#wall)" d="M0 0h600v310H0z"/><path fill="#e9e4ce" d="M0 0h135v310H0z"/><path fill="#636f58" d="M152 0h330v225H152z"/><path fill="url(#window)" d="M160 0h314v217H160z"/><path fill="#8da077" d="M170 170Q205 20 250 85Q300 0 331 130Q391 0 449 100l25 117H160Z"/><path fill="#536b4a" opacity=".5" d="M165 217q45-137 92-55 49-136 98-11 40-107 99 66Z"/><path stroke="#737b62" stroke-width="8" d="M312 0v220M155 122h323"/><path fill="#d9d1b7" d="M0 225h600v85H0z"/><path fill="#7b6951" d="m50 235 260-15 30 20-272 20Z"/><path fill="#4e5140" d="m72 259 11-1-8 52H63Zm230-16 12-2 13 69h-11Z"/><path fill="#8c7758" d="m352 242 208-12 29 20-221 16Z"/><path fill="#555944" d="m380 264 10-1-5 47h-10Zm164-10 10-1 9 57h-10Z"/><path fill="#f2efdf" d="M218 209h29l-3 18h-22Z"/><path stroke="#f2efdf" stroke-width="4" fill="none" d="M247 212q17-2 9 10h-11"/><path fill="#685e46" d="M225 207h16v3h-16Z"/><path fill="#78815a" d="M515 167h36l-5 58h-27Z"/><path stroke="#586e47" stroke-width="5" d="M532 173v-67m0 40-23-22m24 10 21-25"/><ellipse fill="#5b754c" cx="506" cy="117" rx="11" ry="26" transform="rotate(-35 506 117)"/><ellipse fill="#728856" cx="551" cy="105" rx="12" ry="28" transform="rotate(30 551 105)"/><ellipse fill="#526e43" cx="531" cy="90" rx="12" ry="30"/><path fill="#555d45" d="M40 0h4v70h-4Z"/><path fill="#eae6cc" d="M15 83q27-38 55 0Z"/><path fill="#8d8065" d="M407 0h3v45h-3Z"/><path fill="#ece6cf" d="M385 59q24-32 47 0Z"/></svg>`;}
function render(){const r=room(),personal=roomId==='personal',places=visiblePlaces();if(!places.some(p=>p.id===selected))selected=places[0]?.id;resizeObserver?.disconnect();app.innerHTML=`<div class="app"><aside class="sidebar"><button class="close-mobile" data-action="menu" aria-label="메뉴 닫기">${icon('close')}</button><div class="brand"><span class="brand-icon">${icon('pin')}</span>지도메이트</div><p class="tagline">모두의 추천보다, 내 메이트의 추천.</p><button class="nav-btn ${personal?'active':''}" data-room="personal">${icon('map')}내 지도<span class="count">${db.places.filter(p=>p.owner==='me').length}</span></button><button class="nav-btn ${onlyVisited?'active':''}" data-action="visited">${icon('check')}내가 가본 곳</button><div class="section-label">MY MATE ROOMS <span>${db.rooms.filter(r=>r.members.includes('me')).length}</span></div>${db.rooms.filter(r=>r.members.includes('me')).map(r=>`<button class="room-btn ${r.id===roomId?'active':''}" data-room="${r.id}"><span class="room-emoji">${r.emoji}</span>${esc(r.name)}<small>${r.members.length}</small></button>`).join('')}${cloud?.active&&cloud.personal.pendingRoomKeys.length?`<p class="note-box" style="margin:10px 0">가입 승인 대기 ${cloud.personal.pendingRoomKeys.length}개 방<br>${cloud.personal.pendingRoomKeys.map(esc).join('<br>')}</p>`:''}<div class="sidebar-actions"><button data-action="create">${icon('plus')} 방 만들기</button><button data-action="join">초대 코드 입력</button></div><div class="trust-note">${icon('shield')}<h3>우리의 지도는 우리가 관리해요.</h3><p>믿을 수 있는 메이트의 경험만.<br>내 기록은 언제나 나의 것으로.</p></div><div class="profile">${avatar('me')}<div><strong>${esc(user('me').name)}</strong><small>나의 취향을 기록하는 중</small></div><button data-action="profile" aria-label="프로필 설정">${icon('settings')}</button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand"><button class="menu-btn" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button>${icon('pin')}지도메이트</div><div class="breadcrumb">나의 공간 ${icon('chevron')} <strong>${personal?'내 지도':esc(r?.name)}</strong></div><div class="top-actions"><button class="local-badge" data-action="connection"><span class="live-dot"></span> ${cloud?.active?(cloudUnsure?'저장 확인 필요':'내 기록'):'닉네임으로 시작'}</button><button data-action="refresh" title="서버 새로고침" aria-label="서버 새로고침">${icon('locate')}</button><button data-action="install" title="홈 화면에 추가" aria-label="홈 화면에 추가">${icon('share')}</button>${avatar('me')}</div></header><section class="workspace"><div class="room-header"><div><p class="eyebrow">${personal?'YOUR OWN LITTLE WORLD':'A MAP, MADE BY US'}</p><h1>${personal?'나의 취향 지도':esc(r?.name)} <span>${personal?'PRIVATE':'MATES ONLY'}</span></h1><p class="description">${personal?'내가 발견한 장소와 경험. 원하는 메이트에게만 나눠요.':esc(r?.description)}</p></div><div class="header-actions">${!personal?`<button class="btn" data-action="share">${icon('share')} 내 장소 배포</button>`:''}</div></div><div class="members-line"><div class="avatar-stack">${(personal?['me']:r.members).map(avatar).join('')}</div><span><b>${personal?'나만의 기록':`메이트 ${r.members.length}명`}</b>이 함께 만드는 지도</span>${!personal?`<button class="room-manage" data-action="manage">${icon('settings')} 방 관리</button>`:''}</div><div class="toolbar"><button class="btn" data-action="search-store">${icon('search')} 장소 검색</button><div class="filters">${['전체',...categories()].map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${esc(c)}">${c==='전체'?'':icon(categoryIcon(c))+' '}${esc(c)}</button>`).join('')}<button class="chip" data-action="add-category">+ 카테고리</button></div></div><div class="map-layout"><div class="map-shell"><div class="map" id="map"></div><div class="map-label"><i></i><b>${onlyVisited?'내가 가본 장소':'우리의 발견'}</b><span class="map-count">${places.length}개의 소중한 장소</span></div><div class="map-controls"><button data-action="recenter" aria-label="장소 중심으로 이동">${icon('locate')}</button><button data-action="zoom-in" aria-label="지도 확대">${icon('plus')}</button><button data-action="zoom-out" aria-label="지도 축소">${icon('minus')}</button></div><div class="map-provider-note">${esc(naverView.ready?'NAVER 지도':naverNotice)}</div><div class="map-hint">${icon('shield')} ${personal?'내 기록은 나에게, 공유는 선택한 방에만':'이 지도는 우리 메이트에게만 보여요'}</div><div class="attribution">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap</a> contributors</div></div><section class="places-below" aria-label="장소 목록과 지역 필터">${regionHTML()}<div id="place-list">${placeListHTML()}</div></section><aside class="detail" id="detail" ${detailOpen?'':'hidden'}><button class="detail-close" data-action="close-detail">상세보기 닫기 ×</button>${detailHTML()}</aside></div><footer class="footer"><span>© 2026 LUCENTY LABS. All rights reserved.</span></footer></section></main></div>`;bindMap();}
function detailHTML(){const p=db.places.find(p=>p.id===selected);if(!p)return '<div class="empty">아직 장소가 없어요.<br>새로운 발견을 등록해 보세요.<br><button class="btn primary" data-action="add">장소 등록</button></div>';const rs=reviews(p),rated=rs.filter(r=>r.visited&&r.rating),mine=db.reviews.find(r=>samePlace(r,p.id)&&r.user==='me'),members=roomId==='personal'?['me']:room().members;return `<div class="place-art">${art(p.category)}<span class="art-tag">${icon(categoryIcon(p.category))} 메이트의 발견</span><button class="favorite ${p.owner==='me'?'saved':''}" data-action="save-place" aria-label="내 지도에 저장">${icon('heart')}</button></div><div class="detail-body"><p class="place-category">${esc(p.category)}</p><h2>${esc(p.name)}</h2><p class="address">${icon('pin')}${esc(p.address)}</p><div class="owner-row">${avatar(p.owner)}<b>${esc(user(p.owner).name)}</b>님의 발견<span class="date">${p.checked?'직접 확인 '+esc(p.checked):'직접 확인일 미등록'}</span></div><div class="rating-summary"><span class="big">${rating(p)}</span><div><div class="stars">${rated.length?'★'.repeat(Math.round(Number(rating(p))))+'☆'.repeat(5-Math.round(Number(rating(p)))):'☆☆☆☆☆'}</div><div class="tiny">${roomId==='personal'?'나의':'우리 메이트의'} 종합 평점</div></div><div class="review-count">${rated.length}명 평가<br>${rs.filter(r=>r.visited).length}명 방문</div></div><div class="detail-section"><div class="section-heading"><h3>메이트 방문 현황</h3><small>${rs.filter(r=>r.visited).length} / ${members.length}명 방문</small></div><div class="visitors">${members.map(id=>`<div class="visitor ${rs.some(r=>r.user===id&&r.visited)?'visited':''}">${avatar(id)}<span>${id==='me'?'나':esc(user(id).name)}</span></div>`).join('')}</div><button class="visit-toggle" data-action="visit"><span>${mine?.visited?'✓ 나도 가봤어요':'나도 가본 곳인가요?'}</span><span class="switch ${mine?.visited?'on':''}"></span></button></div><div class="detail-section"><div class="section-heading"><h3>메이트들의 평가</h3><small>사람을 눌러 자세히 보기</small></div>${rs.filter(r=>r.visited&&(r.rating||r.custom.length||r.comment)).map(r=>`<button class="review-person" data-review="${r.user}">${avatar(r.user)}<span><strong>${esc(user(r.user).name)}${r.user==='me'?' (나)':''}</strong><small>직접 방문 · ${r.custom.length}가지 나만의 기준</small></span><span class="score">${r.rating?'★ '+r.rating.toFixed(1):'미평가'}</span>${icon('chevron')}</button>`).join('')||'<p class="tiny">첫 번째 경험을 나눠주세요.</p>'}<p class="review-caption">같은 공간, 서로 다른 취향.<br>숫자보다 메이트의 이야기를 들여다보세요.</p><button class="btn full" style="width:100%" data-action="review">${icon('edit')} 나의 경험 기록하기</button>${p.owner==='me'?'<button class="delete-link" data-action="edit-place">장소 정보 수정</button>':''}</div></div>`;}
const world=(lat,lng,z)=>{const s=256*2**z,sin=Math.sin(lat*Math.PI/180);return{x:(lng+180)/360*s,y:(.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*s};};
function drawMap(){const el=document.querySelector('#map');if(!el)return;if(naverView.ready){document.querySelector('.attribution')?.remove();naverView.mount(el,{center,zoom,places:visiblePlaces(),selected,onSelect:openPlaceDetail,onMove:(c,z)=>{center=c;zoom=z;}});return;}const w=el.clientWidth,h=el.clientHeight,c=world(center.lat,center.lng,zoom),left=c.x-w/2,top=c.y-h/2;let html='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+h)/256);y++){if(y<0||y>=2**zoom)continue;html+=`<img class="tile" draggable="false" alt="" src="https://tile.openstreetmap.org/${zoom}/${((x%2**zoom)+2**zoom)%2**zoom}/${y}.png" style="left:${x*256-left}px;top:${y*256-top}px">`;}html+='<div class="map-wash"></div>';for(const p of visiblePlaces()){const a=world(p.lat,p.lng,zoom);html+=`<button class="map-pin ${p.id===selected?'selected':''}" data-place="${p.id}" style="left:${a.x-left}px;top:${a.y-top}px" aria-label="${esc(p.name)}"><span class="pin-label">${esc(p.name)}</span><span class="pin-body">${icon(categoryIcon(p.category))}</span></button>`;}el.innerHTML=html;}
function bindMap(){const el=document.querySelector('#map');naverView.ensure(getMapConfig).then(ready=>{if(ready){naverNotice='NAVER 지도';drawMap();document.querySelector('.attribution')?.remove();}}).catch(error=>{naverNotice=naverError(error);const notice=document.querySelector('.map-provider-note');if(notice)notice.textContent=naverNotice;});resizeObserver=new ResizeObserver(drawMap);resizeObserver.observe(el);let start=null,moved=false;el.addEventListener('pointerdown',e=>{if(naverView.ready||e.target.closest('button'))return;start={x:e.clientX,y:e.clientY,c:world(center.lat,center.lng,zoom)};moved=false;el.setPointerCapture(e.pointerId);el.classList.add('dragging');});el.addEventListener('pointermove',e=>{if(naverView.ready||!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>3)moved=true;const s=256*2**zoom,x=start.c.x-dx,y=start.c.y-dy;center.lng=x/s*360-180;center.lat=Math.atan(Math.sinh(Math.PI*(1-2*y/s)))*180/Math.PI;drawMap();});const end=()=>{start=null;el.classList.remove('dragging');};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);drawMap();}
function modal(title,body,onSubmit){modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="닫기">${icon('close')}</button></div>${onSubmit?`<form id="modal-form">${body}</form>`:body}</section></div>`;if(onSubmit)document.querySelector('#modal-form').addEventListener('submit',e=>{e.preventDefault();if(!cloudBusy)onSubmit(new FormData(e.target));});setTimeout(()=>modalRoot.querySelector('input,textarea,button')?.focus(),0);}
function close(){if(!cloudBusy)modalRoot.innerHTML='';}
async function mutate(fn,message){
  if(cloudBusy)return;
  if(!cloud?.active){fn();save();close();render();if(message)toast(message);return;}
  if(cloudUnsure)return toast('먼저 서버 새로고침으로 최신 기록을 확인해주세요.');
  const before=structuredClone(db),previousRoom=roomId,previousSelected=selected;
  try{fn();setCloudBusy(true);await cloud.saveView(db);await refreshCloud();setCloudBusy(false);close();if(message)toast(message);}
  catch(error){db=before;roomId=previousRoom;selected=previousSelected;cloudUnsure=true;render();showCloudError(error);}
  finally{setCloudBusy(false);}
}
let registrationRatingIndex=0;
function registrationStars(name,value=0){return `<div class="registration-stars" role="group" aria-label="종합 별점">${[0,1,2,3,4,5].map(n=>`<label><input type="radio" name="${name}" value="${n}" ${n===value?'checked':''}><span>${n?'★'.repeat(n):'평가 없음'}</span></label>`).join('')}</div>`;}
function registrationCustomRow(c={label:'',score:0}){const id=registrationRatingIndex++;return `<div class="registration-custom-row"><input name="criterion" aria-label="평가 항목" maxlength="25" placeholder="예: 맛, 의자 편안함" value="${esc(c.label)}"><select name="criterionScore" aria-label="항목 별점">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${n===c.score?'selected':''}>${n?'★'.repeat(n):'평가 없음'}</option>`).join('')}</select><button type="button" data-remove-place-rating="${id}" aria-label="평가 항목 삭제">×</button></div>`;}
function placeForm(edit=false,prefill=null){
  const p=edit?db.places.find(p=>p.id===selected):prefill;
  const previous=p&&db.reviews.find(r=>samePlace(r,p.id||p.canonicalId)&&r.user==='me');
  const state=previous?.visited?'visited':p?.wanted?'wanted':'saved';
  modal(edit?'장소 정보 수정':'장소와 나의 경험 기록',`<p class="intro">개인 지도에 저장돼요. 방에 나누고 싶을 땐 ‘내 장소 배포’를 눌러주세요.</p><label class="field">장소 이름<input name="name" required maxlength="60" value="${esc(p?.name||'')}" placeholder="어떤 곳을 발견했나요?"></label><label class="field">카테고리<input name="category" list="category-options" required maxlength="30" value="${esc(p?.category||'기타')}" placeholder="선택하거나 새 카테고리 입력"><datalist id="category-options">${categories().map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist></label><p class="tiny">자동 분류는 업종을 기준으로 한 제안이에요. 원하는 이름을 직접 입력해도 돼요.</p><label class="field">주소<input name="address" required maxlength="150" value="${esc(p?.address||'')}"></label><details class="coordinate-details"><summary>위치 좌표 확인·수정</summary><div class="two-col"><label class="field">위도<input type="number" name="lat" step="any" min="-85" max="85" required value="${p?.lat||center.lat.toFixed(6)}"></label><label class="field">경도<input type="number" name="lng" step="any" min="-180" max="180" required value="${p?.lng||center.lng.toFixed(6)}"></label></div></details><fieldset class="place-status"><legend>나의 장소 기록</legend>${[['saved','그냥 저장'],['wanted','가보고 싶은 곳'],['visited','가본 곳']].map(([v,label])=>`<label><input type="radio" name="placeStatus" value="${v}" ${state===v?'checked':''}>${label}</label>`).join('')}</fieldset><section id="registration-review" ${state==='visited'?'':'hidden'}><h3>나의 평가 <small>모두 선택사항</small></h3>${registrationStars('overallRating',previous?.rating||0)}<div id="registration-custom">${(previous?.custom||[]).map(registrationCustomRow).join('')}</div><button type="button" class="btn" data-add-place-rating>+ 평가 항목</button><label class="field">한 줄 평<textarea name="placeComment" maxlength="300" placeholder="직접 느낀 점을 남겨주세요">${esc(previous?.comment||'')}</textarea></label></section><label class="check-row"><input type="checkbox" name="checked" ${p?.checked?'checked':''}>직접 장소 정보를 확인했어요</label><button class="btn primary full">${edit?'수정 내용 저장':'장소 저장하기'}</button>${edit?'<button type="button" class="delete-link" data-action="delete-place">내 장소 원본 삭제</button>':''}`,f=>{
    const status=f.get('placeStatus'),data={name:f.get('name').trim(),category:f.get('category').trim(),address:f.get('address').trim(),lat:Number(f.get('lat')),lng:Number(f.get('lng')),wanted:status==='wanted',checked:f.has('checked')?new Date().toLocaleDateString('sv-SE'):null};
    if(!data.name||!data.address||!data.category)return;
    const labels=f.getAll('criterion'),scores=f.getAll('criterionScore'),custom=labels.map((label,i)=>({label:label.trim(),score:Number(scores[i])})).filter(c=>c.label&&c.score>0);
    if(new Set(custom.map(c=>c.label)).size!==custom.length)return toast('평가 항목 이름이 겹치지 않게 입력해주세요.');
    mutate(()=>{const id=edit?p.id:crypto.randomUUID(),canonicalId=p?.canonicalId||id;if(edit)Object.assign(p,data);else db.places.push({...data,id,canonicalId,owner:'me',rooms:[]});const old=db.reviews.findIndex(r=>r.user==='me'&&(r.place===canonicalId||r.place===id));if(old>=0)db.reviews.splice(old,1);if(status==='visited')db.reviews.push({place:canonicalId,user:'me',visited:true,rating:Number(f.get('overallRating')||0),custom,comment:f.get('placeComment').trim()});if(!edit){roomId='personal';selected=id;filter='전체';query='';statusWanted=false;statusVisited=false;center={lat:data.lat,lng:data.lng};}},edit?'장소와 경험을 수정했어요.':'내 지도에 저장했어요. 공유는 원하는 방에서 선택해 주세요.');
  });
}

let draft;
function reviewForm(){let r=db.reviews.find(r=>samePlace(r,selected)&&r.user==='me');draft=structuredClone(r||{place:placeKey(selected),user:'me',visited:true,rating:0,custom:[],comment:''});draft.visited=true;renderReviewForm();}
function starButtons(score,idx){return `<div class="star-input" role="group" aria-label="${idx<0?'종합':esc(draft.custom[idx].label)} 별점">${[1,2,3,4,5].map(n=>`<button type="button" class="${n<=score?'filled':''}" data-star="${idx}:${n}" aria-label="${n}점">★</button>`).join('')}<button type="button" style="font-size:10px;color:#99a18f;margin-left:auto" data-star="${idx}:0">지우기</button></div>`;}
function renderReviewForm(){modal('나의 경험 기록하기',`<p class="intro">${esc(db.places.find(p=>p.id===selected).name)}<br>직접 경험한 것만, 나만의 기준으로 남겨요.</p><div class="custom-heading"><b>종합 평점</b><small>선택사항</small></div>${starButtons(draft.rating,-1)}<div id="custom-ratings">${draft.custom.map((c,i)=>`<div class="custom-rating"><div class="custom-heading"><b>${esc(c.label)}</b><button type="button" data-remove-rating="${i}" aria-label="평가 항목 삭제">${icon('close')}</button></div>${starButtons(c.score,i)}</div>`).join('')}</div><div style="display:flex;gap:8px;margin:16px 0"><input id="custom-name" placeholder="예: 의자 편안함, 커피 맛" maxlength="25" style="min-width:0;flex:1;padding:10px;border:1px solid #dfe5d7;border-radius:7px"><button type="button" class="btn" data-action="add-rating">${icon('plus')} 항목</button></div><label class="field">나의 한 줄 평<textarea id="review-comment" maxlength="300" placeholder="메이트에게 전하고 싶은 경험">${esc(draft.comment)}</textarea></label><p class="note-box">저장하면 방문한 곳으로 표시돼요. 평가하지 않은 항목은 0점이 아닌 ‘평가 없음’이에요. 공유 중인 방의 현재 메이트에게 동일하게 반영돼요.</p><button class="btn primary full">경험 저장하기</button>`,()=>mutate(()=>{draft.comment=document.querySelector('#review-comment').value.trim();draft.custom=draft.custom.filter(c=>c.score>0);const index=db.reviews.findIndex(r=>samePlace(r,selected)&&r.user==='me');draft.place=placeKey(selected);if(index>=0)db.reviews[index]=draft;else db.reviews.push(draft);},'나의 경험을 저장했어요.'));}
function shareForm(){const mine=db.places.filter(p=>p.owner==='me');modal('내 장소 배포',`<p class="intro">${esc(room().name)}에 공유할 장소를 골라주세요.<br>체크를 해제하면 이 방에서만 공유가 해제돼요.</p>${mine.length?`<label class="check-row"><input type="checkbox" id="select-all" ${mine.every(p=>p.rooms.includes(roomId))?'checked':''}>전체 선택 <small>${mine.length}개 장소</small></label>${mine.map(p=>`<label class="check-row"><input type="checkbox" name="place" value="${p.id}" ${p.rooms.includes(roomId)?'checked':''}>${esc(p.name)}<small>${esc(p.category)}</small></label>`).join('')}<button class="btn primary full">선택한 장소 공유하기</button>`:'<p class="empty">아직 내가 등록한 장소가 없어요.<br>내 지도에 장소를 먼저 등록해주세요.</p>'}`,f=>mutate(()=>{const ids=f.getAll('place');for(const p of mine){p.rooms=p.rooms.filter(id=>id!==roomId);if(ids.includes(p.id))p.rooms.push(roomId);}},'이 방에 공유하는 장소를 변경했어요.'));}
function manage(){const r=room(),master=r.master==='me';modal('메이트 & 방 관리',`<p class="intro">${esc(r.name)} · ${r.members.length}명의 메이트<br>${master?'방장으로서 가입 승인, 밴, 권한 위임을 관리해요.':'가입 승인과 밴은 방장이 관리해요.'}</p><p class="note-box">${cloud?.active?'변경 사항은 GitHub에 저장돼요. 새로고침하면 최신 가입 요청을 확인할 수 있어요.':'로컬 체험 데이터예요. 개인 저장소를 연결하면 메이트를 초대할 수 있어요.'}</p>${master?`<div class="section-heading" style="margin-top:22px"><h3>초대 코드</h3><button class="text-btn" data-action="copy-code">복사</button></div><p style="font-size:24px;letter-spacing:5px">${esc(r.code)}</p><p class="tiny">코드를 입력해도 방장 승인 전에는 입장할 수 없어요.</p>`:''}<div class="section-heading" style="margin-top:25px"><h3>함께하는 메이트</h3></div>${r.members.map(id=>`<div class="member-row">${avatar(id)}<span class="member-name">${esc(user(id).name)} ${id==='me'?'(나)':''}</span>${r.master===id?'<small>방장</small>':master?`<button class="text-btn" data-transfer="${id}">위임</button><button class="text-btn danger" data-ban="${id}">밴</button>`:''}</div>`).join('')}${master?`<div class="section-heading" style="margin-top:25px"><h3>승인 대기</h3><small>${r.pending.length}명</small></div>${r.pending.map(id=>`<div class="member-row"><span class="member-name">${esc(user(id).name)}</span><button class="text-btn" data-approve="${id}">승인</button><button class="text-btn danger" data-reject="${id}">거절</button></div>`).join('')||'<p class="tiny">아직 가입 요청이 없어요.</p>'}<div class="section-heading" style="margin-top:25px"><h3>밴 목록</h3><small>${r.bans.length}명</small></div>${r.bans.map(id=>`<div class="member-row"><span class="member-name">${esc(user(id).name)}</span><button class="text-btn" data-unban="${id}">밴 해제</button></div>`).join('')||'<p class="tiny">차단된 메이트가 없어요.</p>'}`:''}<button class="delete-link" data-action="leave">${master?'방을 떠나려면 먼저 방장을 위임해주세요':'이 방에서 탈퇴하기'}</button>`);}
function confirmAction(title,text,fn){modal(title,`<p class="intro">${esc(text)}</p><button class="btn primary full" id="confirm-action">확인</button>`);document.querySelector('#confirm-action').onclick=fn;}
let searchComposing=false;
function updateSearchResults(input){
  if(query===input.value)return;
  query=input.value;
  const places=visiblePlaces();
  if(!places.some(p=>p.id===selected))selected=places[0]?.id;
  // Keep the search input mounted so the browser retains its IME and caret state.
  const count=app.querySelector('.map-count');
  if(count)count.textContent=`${places.length}개의 소중한 장소`;
  document.querySelector('#detail').innerHTML=detailHTML();
  const list=app.querySelector('.list-grid');
  if(list)list.innerHTML=places.length?places.map(p=>`<button class="list-card" data-place="${p.id}">${icon(categoryIcon(p.category))}<h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${esc(user(p.owner).name)}의 발견</p><p>★ ${rating(p)} · ${reviews(p).filter(r=>r.visited).length}명 방문</p></button>`).join(''):'<p class="empty">아직 표시할 장소가 없어요.<br>장소를 등록하거나 검색 조건을 바꿔보세요.</p>';
  drawMap();
}
app.addEventListener('change',e=>{if(e.target.id==='status-wanted'||e.target.id==='status-visited'){if(e.target.id==='status-wanted')statusWanted=e.target.checked;else statusVisited=e.target.checked;detailOpen=false;render();return;}if(e.target.id==='region-city'){regionCity=e.target.value;regionDistrict='';detailOpen=false;render();}if(e.target.id==='region-district'){regionDistrict=e.target.value;detailOpen=false;render();}});
app.addEventListener('compositionstart',e=>{if(e.target.id==='search')searchComposing=true;});
app.addEventListener('compositionend',e=>{if(e.target.id==='search'){searchComposing=false;updateSearchResults(e.target);}});
app.addEventListener('input',e=>{if(e.target.id==='search'&&!searchComposing&&!e.isComposing)updateSearchResults(e.target);});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||cloudBusy)return;if(b.dataset.room){roomId=b.dataset.room;filter='전체';query='';onlyVisited=false;render();return;}if(b.dataset.filter){filter=b.dataset.filter;detailOpen=false;render();return;}if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.action==='add-category'){modal('카테고리 추가','<label class="field">카테고리 이름<input name="category" required maxlength="30" placeholder="예: 전시, 여행, 술집"></label><button class="btn primary full">추가</button>',f=>{const c=f.get('category').trim();if(!c)return;if(!extraCategories.includes(c))extraCategories.push(c);try{localStorage.setItem('placemate-categories',JSON.stringify(extraCategories));}catch{}close();filter=c;render();});return;}if(b.dataset.action==='clear-region'){regionCity='';regionDistrict='';detailOpen=false;render();return;}if(b.dataset.action==='close-detail'){detailOpen=false;document.querySelector('#detail').hidden=true;return;}if(b.dataset.place){openPlaceDetail(b.dataset.place);return;}if(b.dataset.review){const r=db.reviews.find(r=>samePlace(r,selected)&&r.user===b.dataset.review);modal(`${user(r.user).name}님의 경험`,`<p class="intro">${esc(db.places.find(p=>p.id===selected).name)} · 직접 방문</p><div class="review-detail"><div class="rating-line"><strong>종합</strong><span class="stars">${r.rating?'★'.repeat(r.rating)+'☆'.repeat(5-r.rating):'평가 없음'}</span></div>${r.custom.map(c=>`<div class="rating-line"><span>${esc(c.label)}</span><span class="stars">${'★'.repeat(c.score)}${'☆'.repeat(5-c.score)}</span></div>`).join('')}<p>${esc(r.comment||'아직 한 줄 평이 없어요.')}</p></div>${r.user==='me'?'<button class="btn full" data-action="review">내 평가 수정하기</button>':''}`);return;}action(b.dataset.action);});
modalRoot.addEventListener('input',e=>{if(e.target.id==='review-comment'&&draft)draft.comment=e.target.value;});
modalRoot.addEventListener('change',e=>{if(e.target.name==='placeStatus'){document.querySelector('#registration-review').hidden=e.target.value!=='visited';}if(e.target.id==='select-all')modalRoot.querySelectorAll('input[name="place"]').forEach(i=>i.checked=e.target.checked);});
modalRoot.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay')){close();return;}const b=e.target.closest('button');if(!b||cloudBusy)return;if(b.dataset.addPlaceRating!==undefined){const el=document.querySelector('#registration-custom');if(el.children.length>=15)return toast('평가 항목은 15개까지 추가할 수 있어요.');el.insertAdjacentHTML('beforeend',registrationCustomRow());return;}if(b.dataset.removePlaceRating!==undefined){b.closest('.registration-custom-row').remove();return;}if(b.dataset.findPlace!==undefined){const candidate=searchResults[Number(b.dataset.findPlace)];if(candidate){center={lat:candidate.lat,lng:candidate.lng};placeForm(false,candidate);}return;}const r=room();if(b.dataset.star){const [idx,n]=b.dataset.star.split(':').map(Number);if(idx<0)draft.rating=n;else draft.custom[idx].score=n;renderReviewForm();return;}if(b.dataset.removeRating){draft.custom.splice(Number(b.dataset.removeRating),1);renderReviewForm();return;}if(cloud?.active&&handleCloudAdmin(b))return;if(b.dataset.ban&&r?.master==='me'){const id=b.dataset.ban;confirmAction('이 메이트를 밴할까요?',`${user(id).name}님의 장소와 평가는 이 방에서 사라지고, 재가입이 차단돼요. 개인 원본은 유지돼요.`,()=>{r.bans.push(id);r.members=r.members.filter(u=>u!==id);r.pending=r.pending.filter(u=>u!==id);db.places.filter(p=>p.owner===id).forEach(p=>p.rooms=p.rooms.filter(rid=>rid!==r.id));save();render();manage();toast('메이트를 밴했어요.');});return;}if(b.dataset.unban&&r?.master==='me'){r.bans=r.bans.filter(id=>id!==b.dataset.unban);save();manage();return;}if(b.dataset.transfer&&r?.master==='me'){const id=b.dataset.transfer;confirmAction('방장을 위임할까요?',`${user(id).name}님이 새 방장이 되고, 나는 일반 메이트로 남아요.`,()=>mutate(()=>r.master=id,'방장 권한을 위임했어요.'));return;}if(b.dataset.approve&&r?.master==='me'){const id=b.dataset.approve;if(!r.bans.includes(id)&&!r.members.includes(id))r.members.push(id);r.pending=r.pending.filter(u=>u!==id);save();manage();return;}if(b.dataset.reject&&r?.master==='me'){r.pending=r.pending.filter(u=>u!==b.dataset.reject);save();manage();return;}action(b.dataset.action);});
function localAction(a){const p=db.places.find(p=>p.id===selected);switch(a){case 'close':close();break;case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;case 'visited':onlyVisited=!onlyVisited;render();break;case 'add':placeForm();break;case 'edit-place':placeForm(true);break;case 'share':shareForm();break;case 'manage':manage();break;case 'review':reviewForm();break;case 'visit':{const mine=db.reviews.find(r=>samePlace(r,selected)&&r.user==='me');if(mine?.visited&&(mine.rating||mine.custom.length||mine.comment)){confirmAction('방문 표시를 취소할까요?','방문을 취소하면 내 평가와 한 줄 평도 삭제돼요.',()=>mutate(()=>db.reviews=db.reviews.filter(r=>r!==mine),'방문 표시와 평가를 삭제했어요.'));}else mutate(()=>{if(mine)mine.visited=!mine.visited;else db.reviews.push({place:placeKey(selected),user:'me',visited:true,rating:0,custom:[],comment:''});},mine?.visited?'방문 표시를 취소했어요.':'가본 곳으로 기록했어요.');break;}case 'zoom-in':zoom=Math.min(18,zoom+1);drawMap();break;case 'zoom-out':zoom=Math.max(3,zoom-1);drawMap();break;case 'recenter':center=p?{lat:p.lat,lng:p.lng}:{lat:37.5462,lng:127.046};zoom=15;drawMap();break;case 'save-place':if(p.owner==='me'){toast('이미 내 지도에 저장된 장소예요.');break;}const existing=db.places.find(q=>q.owner==='me'&&q.name===p.name&&q.lat===p.lat&&q.lng===p.lng);if(existing){toast('이미 내 지도에 저장했어요.');break;}mutate(()=>db.places.push({...structuredClone(p),canonicalId:p.canonicalId||p.id,id:crypto.randomUUID(),owner:'me',rooms:[],checked:null}),'내 지도에 별도 저장했어요. 원본 작성자의 평가는 복사하지 않아요.');break;case 'add-rating':{const name=document.querySelector('#custom-name').value.trim();if(!name)return toast('평가할 항목 이름을 적어주세요.');if(draft.custom.some(c=>c.label===name))return toast('이미 추가한 항목이에요.');draft.custom.push({label:name,score:0});renderReviewForm();break;}case 'create':modal('우리만의 지도 만들기','<p class="intro">신뢰하는 사람들과 작은 발견을 모아보세요.</p><label class="field">방 이름<input name="name" required maxlength="30" placeholder="예: 우리들의 맛있는 지도"></label><label class="field">방 소개<input name="description" maxlength="100" placeholder="어떤 취향을 나누고 싶나요?"></label><button class="btn primary full">방 만들기</button>',f=>{if(!f.get('name').trim())return;mutate(()=>{const id=crypto.randomUUID();db.rooms.push({id,name:f.get('name').trim(),description:f.get('description').trim()||'우리의 지도는 우리가 관리한다.',emoji:'🌱',master:'me',code:crypto.randomUUID().slice(0,6).toUpperCase(),members:['me'],bans:[],pending:[]});roomId=id;filter='전체';query='';},'새로운 메이트 방을 만들었어요.');});break;case 'join':modal('메이트의 초대를 받았나요?','<p class="intro">초대 코드를 입력하면 방장에게 가입 요청을 보내요.<br>현재 버전에서는 이 브라우저 안의 방만 찾을 수 있어요.</p><label class="field">초대 코드<input name="code" required maxlength="20" placeholder="초대 코드를 입력하세요" style="text-transform:uppercase"></label><button class="btn primary full">가입 요청하기</button>',f=>{const r=db.rooms.find(r=>r.code===f.get('code').trim().toUpperCase());if(!r)return toast('해당 코드를 가진 방을 찾지 못했어요.');if(r.bans.includes('me'))return toast('이 방에 가입할 수 없는 계정이에요.');if(r.members.includes('me'))return toast('이미 참여 중인 방이에요.');if(r.pending.includes('me'))return toast('방장의 승인을 기다리고 있어요.');mutate(()=>r.pending.push('me'),'가입을 요청했어요. 방장의 승인이 필요해요.');});break;case 'profile':modal('나의 프로필',`<label class="field">닉네임<input name="name" value="${esc(user('me').name)}" required maxlength="15"></label><button class="btn primary full">저장하기</button>`,f=>{if(f.get('name').trim())mutate(()=>user('me').name=f.get('name').trim(),'닉네임을 변경했어요.');});break;case 'copy-code':navigator.clipboard?.writeText(room().code).then(()=>toast('초대 코드를 복사했어요.')).catch(()=>toast('초대 코드: '+room().code));break;case 'leave':{const r=room();if(r.master==='me')return toast('먼저 다른 메이트에게 방장을 위임해주세요.');confirmAction('이 방에서 탈퇴할까요?','이 방에 공유한 내 장소와 평가가 사라져요. 개인 기록과 다른 방의 공유는 유지돼요.',()=>mutate(()=>{r.members=r.members.filter(id=>id!=='me');db.places.filter(p=>p.owner==='me').forEach(p=>p.rooms=p.rooms.filter(id=>id!==r.id));roomId='personal';},'방에서 탈퇴했어요. 내 기록은 그대로예요.'));break;}case 'delete-place':confirmAction('장소 원본을 삭제할까요?','내 개인 지도와 공유한 모든 방에서 이 장소가 삭제돼요. 이 작업은 되돌릴 수 없어요.',()=>mutate(()=>{db.places=db.places.filter(q=>q.id!==p.id);db.reviews=db.reviews.filter(r=>r.place!==p.id);},'장소를 삭제했어요.'));break;case 'install':modal('홈 화면에서 바로 만나요',`<p class="intro">아이폰 Safari에서 이 웹앱을 열고<br><b>공유 ${icon('share')} → 홈 화면에 추가</b>를 선택해주세요.</p><div class="note-box">Android Chrome에서는 메뉴 → ‘홈 화면에 추가’ 또는 ‘앱 설치’를 선택할 수 있어요.<br><br>실제 설치에는 HTTPS로 배포된 주소가 필요해요. APK 패키징은 웹 배포 후 별도로 진행할 수 있어요.</div>`);break;case 'about':modal('지도메이트, 첫 번째 버전','<p class="intro">모두의 추천보다, 내 메이트의 추천.</p><div class="note-box">지금 보이는 메이트와 평가는 체험용 예시예요. 기록은 현재 브라우저에만 저장되며, 기기를 바꾸거나 브라우저 데이터를 지우면 유지되지 않아요.<br><br>실제 다중 사용자 공유, 로그인, 서버 권한 검증, 초대 승인 알림은 아직 연결되지 않았어요. 지도는 OpenStreetMap을 사용하며, 장소 좌표와 정보는 실제 이용 전 확인이 필요해요.</div><button class="btn full" data-action="export">내 기록 백업하기</button>');break;case 'export':{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='jidomate-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('기록을 JSON 파일로 내보냈어요.');break;}}}
function naverError(error){
  const messages={NAVER_SEARCH_NOT_CONFIGURED:'네이버 가게 검색 키가 아직 설정되지 않았어요.',NAVER_BACKEND_UPDATE_REQUIRED:'검색 기능을 사용하려면 Apps Script를 최신 Code.gs로 업데이트해주세요.',UNKNOWN_ACTION:'검색 기능을 사용하려면 Apps Script를 최신 Code.gs로 업데이트해주세요.',NAVER_SEARCH_AUTH_FAILED:'네이버 검색 키 또는 지역 검색 서비스 등록을 확인해주세요.',NAVER_SEARCH_RATE_LIMIT:'검색 요청이 많아요. 잠시 뒤 다시 검색해주세요.',NAVER_SEARCH_DAILY_LIMIT:'오늘 설정된 검색 한도에 도달했어요.',NAVER_SEARCH_FAILED:'네이버 검색 응답을 받지 못했어요. 잠시 뒤 다시 시도해주세요.',NAVER_MAP_AUTH_FAILED:'네이버 지도 키와 등록 도메인을 확인해주세요.',NAVER_MAP_LOAD_FAILED:'네이버 지도 연결을 확인해주세요.',INVALID_SEARCH_QUERY:'가게 이름과 지역을 두 글자 이상 입력해주세요.'};
  return messages[error.code||error.message]||cloudError(error);
}
function searchPlaceForm(){
  searchResults=[];
  modal('실제 가게 찾아 등록하기','<p class="intro">지역과 가게 이름으로 검색해보세요. 예: 성수 센터커피<br>검색 결과를 고르면 주소와 지도 위치가 자동 입력돼요.</p><label class="field">가게 검색<input name="storeQuery" required minlength="2" maxlength="100" placeholder="예: 성수 센터커피" autocomplete="off"></label><button class="btn primary full">네이버에서 검색</button><div id="store-results" aria-live="polite"></div><button type="button" class="text-btn" style="margin-top:20px" data-action="manual-place">직접 입력해서 등록</button>',async f=>{
    const container=document.querySelector('#store-results'),submit=document.querySelector('#modal-form button[type="submit"]')||document.querySelector('#modal-form .primary');
    const word=f.get('storeQuery').trim();if(word.length<2)return;
    submit.disabled=true;container.textContent='가게를 찾고 있어요…';
    try{const result=await cloud.searchPlaces(word);if(document.querySelector('#store-results')!==container)return;searchResults=(result.items||[]).map(p=>({...p,category:['맛집','카페'].includes(p.category)?p.category:'기타'}));container.innerHTML=searchResults.length?'<p class="tiny" style="margin:18px 0 6px">NAVER 지역 검색 · 최대 5개 결과</p>'+searchResults.map((p,i)=>'<button type="button" class="store-result" data-find-place="'+i+'"><strong>'+esc(p.name)+'</strong><span>'+esc(p.address)+'</span><small>'+esc(p.category)+' · 이 가게 선택 →</small></button>').join(''):'<p class="intro">검색 결과가 없어요. 지역과 지점명을 함께 입력해보세요.</p>';}
    catch(error){container.textContent=naverError(error);}
    finally{submit.disabled=false;}
  });
}
function setCloudBusy(value){cloudBusy=value;document.body.classList.toggle('cloud-busy',value);document.querySelector('#cloud-status')?.remove();if(value){const status=document.createElement('div');status.id='cloud-status';status.setAttribute('role','status');status.textContent='서버와 기록을 맞추고 있어요…';document.body.append(status);}}
function showCloudError(error){toast(cloudError(error));const e=document.querySelector('#cloud-error');if(e)e.textContent=cloudError(error);}
async function refreshCloud(){
  db=await cloud.refresh();cloudUnsure=false;
  if(roomId!=='personal'&&!db.rooms.some(r=>r.id===roomId))roomId='personal';
  render();
}
async function cloudCommand(action,payload,message,{manageAfter=false,selectRoom=false}={}){
  if(cloudBusy)return;
  if(cloudUnsure)return toast('먼저 서버 새로고침으로 최신 기록을 확인해주세요.');
  setCloudBusy(true);
  try{
    const result=await cloud.command(action,payload);
    if(selectRoom)roomId=result.room.key;
    await refreshCloud();setCloudBusy(false);close();
    if(manageAfter&&roomId!=='personal')manage();
    toast(message);
  }catch(error){cloudUnsure=true;render();showCloudError(error);}
  finally{setCloudBusy(false);}
}
async function startCloud(){
  const key=localStorage.getItem(SESSION_KEY);
  if(!key){connectionForm();return;}
  cloudKey=key;cloud=CloudStore.connect(key);
  db={users:[{id:'me',name:'메이트',color:'#e7ecd8'}],places:[],reviews:[],rooms:[]};roomId='personal';render();
  setCloudBusy(true);
  try{await refreshCloud();}
  catch(error){cloud=null;showCloudError(error);connectionForm(cloudError(error));}
  finally{setCloudBusy(false);}
}
function connectionForm(error=''){
  if(cloud?.active){
    modal('나의 기록',`<p class="intro">${esc(user('me').name)}님의 장소와 평가는 GitHub에 저장돼요.<br>다른 기기에서는 개인키로 같은 기록을 열 수 있어요.</p><div class="note-box">개인키는 로그인·복구 수단이에요. 잃어버리지 않게 보관하고 다른 사람에게 공유하지 마세요.</div><button class="btn full" data-action="backup-key">개인키 백업 파일 받기</button><button class="btn full" data-action="refresh">서버 기록 새로고침</button><button class="btn full" data-action="about">서비스 안내</button><button class="delete-link" data-action="disconnect">이 기기에서 로그아웃</button>`);return;
  }
  modal('지도메이트 시작하기',`<p class="intro">메이트에게 보여줄 닉네임을 알려주세요.<br>설정 후 방을 만들거나 방번호로 입장할 수 있어요.</p><label class="field">나의 닉네임<input name="nickname" maxlength="15" placeholder="메이트들에게 보여줄 이름"></label><button type="button" class="btn primary full" data-action="register-cloud">닉네임으로 시작하기</button><details class="detail-section"><summary>다른 기기의 기록 가져오기</summary><label class="field">기록 복구 코드<input name="personalKey" type="password" autocomplete="off" spellcheck="false" maxlength="64" placeholder="64자리 개인키"></label><button type="button" class="btn full" data-action="login-cloud">기존 기록 불러오기</button></details><p id="cloud-error" role="alert" class="danger" style="font-size:12px;line-height:1.8;margin-top:15px">${esc(error)}</p><p class="tiny" style="line-height:1.9">별도 아이디·비밀번호 없이 시작해요.<br>기기를 옮길 때는 내 기록 메뉴에서 복구 코드를 백업할 수 있어요.</p>`);
}
async function connectCloud(register){
  if(cloudBusy)return;
  let key=register?localStorage.getItem('jidomate-pending-key')||generatePersonalKey():modalRoot.querySelector('[name="personalKey"]').value.trim();
  if(!/^[a-f0-9]{64}$/.test(key))return showCloudError(new Error('INVALID_PERSONAL_KEY'));
  const nickname=modalRoot.querySelector('[name="nickname"]')?.value.trim();
  if(register&&!nickname)return toast('닉네임을 입력해주세요.');
  setCloudBusy(true);
  try{
    const candidate=CloudStore.connect(key);
    if(register){
      // Retain the key before transmission: a timed-out registration may have committed.
      localStorage.setItem('jidomate-pending-key',key);
      try{await candidate.command('register',{nickname});}catch(e){if(e.code!=='ACCOUNT_EXISTS')throw e;}
    }
    const nextDb=await candidate.refresh();
    localStorage.setItem(SESSION_KEY,key);localStorage.removeItem('jidomate-pending-key');
    cloud=candidate;cloudKey=key;cloudUnsure=false;db=nextDb;roomId='personal';filter='전체';query='';selected=null;
    setCloudBusy(false);close();render();
    if(register)modal('지도메이트에 온 걸 환영해요',`<p class="intro">닉네임 설정이 끝났어요. 방을 만들거나 초대받은 방번호를 입력해보세요.<br>내 기록은 이 기기에서 자동으로 이어져요.</p><button class="btn primary full" data-action="create">새 방 만들기</button><button class="btn full" data-action="join">방번호로 입장하기</button>`);
    toast(register?'시작할 준비가 됐어요.':'개인 기록을 불러왔어요.');
  }catch(error){showCloudError(error);}
  finally{setCloudBusy(false);}
}
function handleCloudAdmin(b){
  const entries=[['ban','밴','장소와 평가가 이 방에서 사라지고 재가입이 차단돼요. 개인 원본은 유지돼요.'],['transfer','방장 위임','선택한 메이트에게 방장 권한을 넘기고 나는 일반 메이트로 남아요.'],['unban','밴 해제',''],['approve','가입 승인',''],['reject','가입 거절','']];
  for(const [command,label,description]of entries){
    const id=b.dataset[command];if(!id)continue;
    const r=room(),payload={roomKey:r.id,expectedRevision:r.revision,userId:id};
    const execute=()=>cloudCommand(command,payload,label+' 처리를 저장했어요.',{manageAfter:command!=='transfer'});
    if(description)confirmAction(label+'할까요?',`${user(id).name}님: ${description}`,execute);else execute();
    return true;
  }
  return false;
}
function action(a){
  if(cloudBusy)return;
  if(a==='add'||a==='search-store'){if(!cloud?.active)return connectionForm();searchPlaceForm();return;}
  if(a==='manual-place'){placeForm();return;}
  if(a==='connection'){connectionForm();return;}
  if(a==='register-cloud'){connectCloud(true);return;}
  if(a==='login-cloud'){connectCloud(false);return;}
  if(a==='backup-key'){
    const url=URL.createObjectURL(new Blob([cloudKey+'\n'],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='지도메이트-개인키.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('개인키를 안전한 곳에 보관해주세요.');return;
  }
  if(a==='disconnect'){
    confirmAction('이 기기에서 로그아웃할까요?','GitHub 기록은 유지돼요. 다시 접속하려면 백업한 개인키가 필요해요.',()=>{localStorage.removeItem(SESSION_KEY);cloud=null;cloudKey='';cloudUnsure=false;db=structuredClone(initial);roomId='friends';close();render();toast('이 기기에서 로그아웃했어요.');});return;
  }
  if(a==='refresh'){
    if(!cloud?.active){if(localStorage.getItem(SESSION_KEY))startCloud();else connectionForm();return;}
    setCloudBusy(true);refreshCloud().then(()=>{setCloudBusy(false);close();toast('최신 기록을 불러왔어요.');}).catch(showCloudError).finally(()=>setCloudBusy(false));return;
  }
  if(!cloud?.active){
    if(['create','join','share','add','edit-place','delete-place','review','visit','save-place','profile','manage'].includes(a)){connectionForm();return;}
    if(a==='about'){connectionForm();return;}
    localAction(a);return;
  }
  switch(a){
    case 'create':modal('우리만의 지도 만들기','<p class="intro">새 방키를 만들고 GitHub에 저장해요.</p><label class="field">방 이름<input name="name" required maxlength="30"></label><label class="field">방 소개<input name="description" maxlength="100"></label><button class="btn primary full">방 만들기</button>',f=>cloudCommand('createRoom',{name:f.get('name').trim(),description:f.get('description').trim()},'방을 만들었어요. 방키를 메이트에게 알려주세요.',{selectRoom:true}));return;
    case 'join':modal('초대 코드로 가입 요청','<p class="intro">코드를 입력하면 방장에게 가입 요청을 보내요.<br>승인 후 서버 새로고침을 누르면 방이 나타나요.</p><label class="field">방키<input name="code" required pattern="[a-fA-F0-9]{12}" minlength="12" maxlength="12" placeholder="12자리 초대 코드" style="text-transform:uppercase"></label><button class="btn primary full">가입 요청하기</button>',f=>cloudCommand('requestJoin',{roomKey:f.get('code').trim().toUpperCase()},'가입을 요청했어요. 방장의 승인을 기다려주세요.'));return;
    case 'share':{
      const r=room(),mine=db.places.filter(p=>p.owner==='me');
      modal('내 장소 배포',`<p class="intro">${esc(r.name)}에 공유할 장소만 골라주세요.<br>체크를 해제하면 이 방에서만 공유가 해제돼요.</p><label class="check-row"><input id="select-all" type="checkbox" ${mine.length&&mine.every(p=>p.rooms.includes(r.id))?'checked':''}>전체 선택 <small>${mine.length}개 장소</small></label>${mine.map(p=>`<label class="check-row"><input type="checkbox" name="place" value="${esc(p.id)}" ${p.rooms.includes(r.id)?'checked':''}>${esc(p.name)}</label>`).join('')}${mine.length?'':'<p class="intro">아직 내가 등록한 장소가 없어요.</p>'}<button class="btn primary full">공유 선택 저장</button>`,f=>cloudCommand('share',{roomKey:r.id,expectedRevision:r.revision,placeIds:f.getAll('place')},'선택한 공유 장소를 저장했어요.'));return;
    }
    case 'leave':{
      const r=room();if(r.master==='me')return toast('다른 메이트에게 방장을 먼저 위임해주세요.');
      confirmAction('이 방에서 탈퇴할까요?','이 방에서 공유만 해제돼요. 내 원본 기록과 다른 방의 공유는 유지돼요.',()=>cloudCommand('leave',{roomKey:r.id,expectedRevision:r.revision},'방에서 탈퇴했어요. 개인 기록은 그대로예요.'));return;
    }
    case 'about':modal('지도메이트 저장 안내','<p class="intro">개인 원본과 방별 공유 정보는 Apps Script를 통해 GitHub에 저장돼요. 새로고침하면 메이트의 최신 기록이 반영돼요.</p><p class="note-box">방키는 가입 요청용이에요. 본인 기록에 접근하는 개인키는 별도로 보관해주세요.<br><br>탈퇴와 밴은 현재 방에서 정보를 제거해요. GitHub 과거 커밋과 다른 사람이 이미 저장한 복사본까지 삭제되지는 않아요.</p><button class="btn full" data-action="export">현재 기록 JSON 백업</button>');return;
    default:localAction(a);
  }
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&modalRoot.firstChild){const items=[...modalRoot.querySelectorAll('button,input,textarea,select')].filter(e=>!e.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}});
render();
startCloud();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

